import json
with open('/private/tmp/claude-501/-Users-taha/c7a33960-1c96-4b0c-b15f-02a996414e54/scratchpad/materials.json') as f:
    d = json.load(f)

# print abstract
def dump_text(node):
    if isinstance(node, dict):
        t = node.get('type')
        if t == 'text':
            return node.get('text','')
        if 'inlineContent' in node:
            return ''.join(dump_text(x) for x in node['inlineContent'])
        if 'content' in node:
            return ''.join(dump_text(x) for x in node['content'])
    if isinstance(node, list):
        return ''.join(dump_text(x) for x in node)
    return ''

print('ABSTRACT:', dump_text(d.get('abstract',[])))
print()
for sec in d.get('primaryContentSections', []):
    print('---SECTION---', sec.get('kind'))
    print(dump_text(sec.get('content', [])))
    print()
